void Solver::rephase() {
    // Reset the rephase counter for the next cycle
    rephases = 0;

    // Make the threshold a little less aggressive than the original (0.9) 
    // to avoid too frequent rephasing while still allowing it to happen.
    threshold = static_cast<int>(threshold * 0.95);

    // Increase the limit more conservatively; this gives the solver
    // a bit more room before the next forced rephase.
    rephase_limit += 4096;

    // ---- Phase‑selection strategy ---------------------------------
    // Mix three different policies:
    //   1) Keep the best phase observed so far (local_best)
    //   2) Use the opposite of the best phase
    //   3) Choose a completely random polarity
    // The probabilities are tuned to favour the known good phase
    // while still injecting diversity to escape stagnation.
    for (int i = 1; i <= vars; ++i) {
        int r = rand() % 100;
        if (r < 45) {                     // 45% keep the best observed phase
            saved[i] = local_best[i];
        } else if (r < 75) {              // 30% flip the best phase
            saved[i] = -local_best[i];
        } else {                          // 25% random polarity
            saved[i] = (rand() & 1) ? 1 : -1;
        }
    }
    // ----------------------------------------------------------------
}
